object Ventilation_Decision_i_control_process_ventilation_decision_SystemTestAPI {
  /** helper method to set the values of all incoming ports
    * @param api_temperature incoming data port
    * @param api_upper_limit incoming data port
    * @param api_validity incoming data port
    */
  def put_concrete_inputs(api_temperature: Greenhouse_Ventilation.Temperature_Celsius,
                          api_upper_limit: Greenhouse_Ventilation.Upper_Temperature_Limit,
                          api_validity: Greenhouse_Ventilation.Temperature_Validity.Type): Unit = {
    put_temperature(api_temperature)
    put_upper_limit(api_upper_limit)
    put_validity(api_validity)
  }

  // setter for incoming data port
  def put_temperature(value: Greenhouse_Ventilation.Temperature_Celsius): Unit = {
    Art.insertInInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.operational_api.temperature_Id, Greenhouse_Ventilation.Temperature_Celsius_Payload(value))
  }

  // setter for incoming data port
  def put_upper_limit(value: Greenhouse_Ventilation.Upper_Temperature_Limit): Unit = {
    Art.insertInInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.operational_api.upper_limit_Id, Greenhouse_Ventilation.Upper_Temperature_Limit_Payload(value))
  }

  // setter for incoming data port
  def put_validity(value: Greenhouse_Ventilation.Temperature_Validity.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.operational_api.validity_Id, Greenhouse_Ventilation.Temperature_Validity_Payload(value))
  }

  def fetchContainer(): greenhouse_ventilation.Greenhouse_Ventilation.Ventilation_Decision_i_control_process_ventilation_decision_PostState_Container_PS = {
    if (runtimeMonitorStream.contains(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.id)) {
      val (_, postContainer_) = runtimeMonitorStream.get(Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.id).get
      return postContainer_.asInstanceOf[greenhouse_ventilation.Greenhouse_Ventilation.Ventilation_Decision_i_control_process_ventilation_decision_PostState_Container_PS]
    }
    else {
      assert(F, s"No post state recorded for ${Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.name}")
      halt(s"No post state recorded for ${Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.name}")
    }
  }

  def check_concrete_outputs(api_fan_command: Greenhouse_Ventilation.Fan_Command.Type,
                             api_sensor_fault: Greenhouse_Ventilation.Sensor_Fault_Indication.Type): Unit = {
    var failureReasons: ISZ[ST] = ISZ()

    val actual_fan_command = get_api_fan_command()
    if (api_fan_command != actual_fan_command) {
      failureReasons = failureReasons :+ st"'fan_command' did not match expected.  Expected: $api_fan_command, Actual: $actual_fan_command"
    }
    val actual_sensor_fault = get_api_sensor_fault()
    if (api_sensor_fault != actual_sensor_fault) {
      failureReasons = failureReasons :+ st"'sensor_fault' did not match expected.  Expected: $api_sensor_fault, Actual: $actual_sensor_fault"
    }

    assert(failureReasons.isEmpty, st"${(failureReasons, "\n")}".render)
  }

  def get_api_fan_command(): Greenhouse_Ventilation.Fan_Command.Type = {
    return fetchContainer().api_fan_command
  }

  def get_api_sensor_fault(): Greenhouse_Ventilation.Sensor_Fault_Indication.Type = {
    return fetchContainer().api_sensor_fault
  }
}